41	namespace mp  = boost::mp11;
42	namespace cmd = ::comdare::cache_engine::builder::commands;
43	
44	/// ycsb_token — Hybrid-Brücke: bestehende compile-time-WorkloadKind (YCSB A–F + IH/LH) → runtime-
45	/// profile_by_name-Token. Custom_*-Ops (WorkloadKind) haben in profile_by_name kein Mess-Lastprofil-Pendant
46	/// → "" (3-Mengen-Vereinheitlichung = offene Design-Folge, Ledger). "" ist zugleich profile_by_name's
47	/// „überspringen"-Marker.
48	[[nodiscard]] constexpr std::string_view ycsb_token(cmd::WorkloadKind k) noexcept {
49	    switch (k) {
50	        case cmd::WorkloadKind::YCSB_A_Read50Write50: return "A";
51	        case cmd::WorkloadKind::YCSB_B_Read95Write5: return "B";
52	        case cmd::WorkloadKind::YCSB_C_ReadOnly: return "C";
53	        case cmd::WorkloadKind::YCSB_D_ReadLatest: return "D";
54	        case cmd::WorkloadKind::YCSB_E_Scan95: return "E";
55	        case cmd::WorkloadKind::YCSB_F_ReadModifyWrite: return "F";
56	        case cmd::WorkloadKind::InsertHeavy: return "IH"; // #31-Schritt-2: → profile_by_name make_insert_heavy (80/20)
57	        case cmd::WorkloadKind::LookupHeavy: return "LH"; // #31-Schritt-2: → profile_by_name make_lookup_heavy (95/5)
58	        case cmd::WorkloadKind::Custom_HotKey:
59	        case cmd::WorkloadKind::Custom_RangeDelete:
60	        case cmd::WorkloadKind::Custom_BulkInsert: return ""; // offene 3-Mengen-Vereinheitlichung
61	    }
62	    return "";
63	}
64	
65	/// ycsb_profile_list — die 6 YCSB-Profile (A–F) als compile-time-Liste = die YCSB-Teilmenge der Workload-Achse W.
66	using ycsb_profile_list =
67	    mp::mp_list<std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_A_Read50Write50>,
68	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_B_Read95Write5>,
69	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_C_ReadOnly>,
70	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_D_ReadLatest>,
71	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_E_Scan95>,
72	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_F_ReadModifyWrite>>;
73	
74	inline constexpr std::size_t ycsb_profile_count = mp::mp_size<ycsb_profile_list>::value;
75	
76	/// workload_profile_list — die VOLLE compile-time-Workload-Achse W der 2D-Mess-Matrix (#31-Schritt-2):
77	/// die 6 YCSB-Profile (A–F) + die 2 Heavy-Profile (IH/LH). Alle 8 haben ein profile_by_name-Mess-Pendant
78	/// (ycsb_token != ""). Additiv am Ende angehängt (mp_push_back) → YCSB-Reihenfolge/-Teilmenge unverändert.
79	using workload_profile_list =
80	    mp::mp_push_back<ycsb_profile_list,
81	                     std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::InsertHeavy>,
82	                     std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::LookupHeavy>>;
83	
84	inline constexpr std::size_t workload_profile_count = mp::mp_size<workload_profile_list>::value;
85	
86	/// config_for — Hybrid: compile-time-WorkloadKind (YCSB A–F) → runtime-WorkloadConfig via profile_by_name
87	/// (bit-identisch delegiert, golden-neutral). seed/ops bleiben runtime (dynamische Achse).
88	[[nodiscard]] inline WorkloadConfig config_for(cmd::WorkloadKind k, std::uint64_t seed, std::size_t ops) {
89	    return profile_by_name(ycsb_token(k), seed, ops);
90	}
91	
92	// ── Self-proving (compile-time) ──────────────────────────────────────────────────────────────────────
93	static_assert(ycsb_profile_count == 6, "#31: 6 YCSB-Profile (A–F) als compile-time-Achse via WorkloadKind-Reuse.");
94	static_assert(workload_profile_count == 8, "#31-Schritt-2: volle Workload-Achse W = 6 YCSB (A–F) + IH/LH.");
95	static_assert(ycsb_token(cmd::WorkloadKind::YCSB_A_Read50Write50) == std::string_view{"A"});
96	static_assert(ycsb_token(cmd::WorkloadKind::YCSB_E_Scan95) == std::string_view{"E"});
97	static_assert(ycsb_token(cmd::WorkloadKind::YCSB_F_ReadModifyWrite) == std::string_view{"F"});
98	static_assert(ycsb_token(cmd::WorkloadKind::InsertHeavy) == std::string_view{"IH"});
99	static_assert(ycsb_token(cmd::WorkloadKind::LookupHeavy) == std::string_view{"LH"});
100	
101	// ── Achse D: die 6 Kanon-Datensätze (#25 / G-6v48, Thesis-tab:datasets — eindeutig fixiert, kein Fork) ──
102	enum class CanonicalDataset : std::uint8_t { Url = 0, Dna, Protein, Xml, TpcdsId, TrecTerms };
103	
104	[[nodiscard]] constexpr std::string_view dataset_name(CanonicalDataset d) noexcept {
105	    switch (d) {
106	        case CanonicalDataset::Url: return "url";
107	        case CanonicalDataset::Dna: return "dna";
108	        case CanonicalDataset::Protein: return "protein";
109	        case CanonicalDataset::Xml: return "xml";
110	        case CanonicalDataset::TpcdsId: return "tpcds-id";
111	        case CanonicalDataset::TrecTerms: return "trec-terms";
112	    }
113	    return "";
114	}
115	
116	using dataset_list = mp::mp_list<std::integral_constant<CanonicalDataset, CanonicalDataset::Url>,
117	                                 std::integral_constant<CanonicalDataset, CanonicalDataset::Dna>,
118	                                 std::integral_constant<CanonicalDataset, CanonicalDataset::Protein>,
119	                                 std::integral_constant<CanonicalDataset, CanonicalDataset::Xml>,
120	                                 std::integral_constant<CanonicalDataset, CanonicalDataset::TpcdsId>,
121	                                 std::integral_constant<CanonicalDataset, CanonicalDataset::TrecTerms>>;
122	
123	inline constexpr std::size_t dataset_count = mp::mp_size<dataset_list>::value;
124	
125	// ── 2D-Mess-Matrix = Achse W (8 Workloads: YCSB A–F + IH/LH) × Achse D (6 Datasets) als compile-time-
126	// Kreuzprodukt (F7-Plan §4). Jede Zelle = mp_list<WorkloadKind-Tag, CanonicalDataset-Tag>; runtime
127	// instanziiert je Mess-Lauf (Hybrid).
128	using matrix_cells                             = mp::mp_product<mp::mp_list, workload_profile_list, dataset_list>;
129	inline constexpr std::size_t matrix_cell_count = mp::mp_size<matrix_cells>::value;
130	
131	static_assert(dataset_count == 6, "#31: 6er-Kanon-Datensätze (#25 / G-6v48).");
132	static_assert(dataset_name(CanonicalDataset::TrecTerms) == std::string_view{"trec-terms"});
133	static_assert(matrix_cell_count == 48,
134	              "#31-Schritt-2: 2D-Mess-Matrix = 8 Workloads (A–F + IH/LH) × 6 Datasets = 48 Zellen.");
135	
136	} // namespace comdare::cache_engine::builder::workload_driver
